          "quote": "Os alunos serão capazes de identificar e descrever os atores, pré-condições, fluxo principal e fluxo alternativo (em especial, a condição que aciona a alternativa de indisponibilidade) em um caso de uso de reserva de uma quadra esportiva."
        }
      ],
      "justification": "O objetivo contempla descrever ator, pré-condição, fluxo principal e fluxo alternativo de indisponibilidade, todos no contexto da reserva de uma quadra esportiva."
    },
    "duration_minutes": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 16,
          "line_end": 16,
          "quote": "50 minutos"
        },
