{
  "schema_version": "eduadocs-requirement-judge-response-v2.0.0",
  "rubric_version": "eduadocs-requirement-judge-v2.0.0",
  "evaluation_id": "eval-12dfc16e3e7bdab5aa055fe42e509282",
  "requirements": {
    "topic": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 37,
          "line_end": 40,
          "quote": "* **Conceito-Chave:** Breve explicação sobre **Critérios de Aceitação** e a sintaxe do BDD (*Behavior-Driven Development*):\n  * **Dado (Given):** O contexto/estado inicial do sistema.\n  * **Quando (When):** A ação do usuário ou evento gerador.\n  * **Então (Then):** O resultado observável (o que muda no estado ou o que a interface exibe)."
        },
        {
          "line_start": 45,
          "line_end": 47,
          "quote": "* **O Desafio:** A partir da folha de regras, cada dupla deve modelar a lógica de negócios para um carrinho de compras, construindo:\n  * **Cenário 1:** Aplicação bem-sucedida de cupom válido.\n  * **Cenário 2:** Tentativa de aplicação de cupom com data retroativa (expirado)."
        }
      ],
      "justification": "O plano trata de critérios de aceitação e os aplica à utilização de cupons em um carrinho de compras, contemplando o tema solicitado."
    },
    "grade_level": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 7,
          "line_end": 7,
          "quote": "* **Público-alvo:** Graduação em Ciência da Computação (Fase Introdutória / 1º ou 2º ano)"
        }
      ],
      "justification": "Estão explícitos tanto o curso de graduação em Ciência da Computação quanto o caráter introdutório da formação."
    },
    "learning_objectives": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 19,
          "line_end": 20,
          "quote": "* Especificar com precisão dois critérios de aceitação no formato **Dado-Quando-Então (Given-When-Then)** — um para cupom de desconto válido e outro para cupom expirado;\n* Justificar os resultados observáveis (efeitos colaterais de negócio e mensagens de interface) derivados dessas regras."
        }
      ],
      "justification": "Os objetivos incluem especificar dois critérios no formato Dado Quando Então, diferenciar cupom válido e expirado e justificar os resultados observáveis."
    },
    "duration_minutes": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 9,
          "line_end": 9,
          "quote": "* **Duração:** 50 minutos"
        },
        {
          "line_start": 33,
          "line_end": 35,
          "quote": "### **Desenvolvimento da Aula (Cronograma: 50 minutos)**\n\n#### **1. Introdução e Contextualização (10 min)**"
        }
      ],
      "justification": "A duração declarada é de 50 minutos. As quatro etapas sequenciais têm 10, 25, 10 e 5 minutos, totalizando os 50 minutos solicitados, sem indicação de sobreposição."
    },
    "methodology": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 43,
          "line_end": 47,
          "quote": "#### **2. Resolução Colaborativa do Problema (25 min)**\n* **Organização:** Os estudantes se organizam em duplas.\n* **O Desafio:** A partir da folha de regras, cada dupla deve modelar a lógica de negócios para um carrinho de compras, construindo:\n  * **Cenário 1:** Aplicação bem-sucedida de cupom válido.\n  * **Cenário 2:** Tentativa de aplicação de cupom com data retroativa (expirado)."
        }
      ],
      "justification": "A resolução de um problema está operacionalizada pela construção conjunta, em duplas, dos dois cenários a partir das regras fornecidas, representando a resolução colaborativa solicitada."
    },
    "materials": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 11,
          "line_end": 13,
          "quote": "* **Materiais e Recursos:** \n  * Quadro branco e marcadores.\n  * Folha de apoio impressa: *\"Regras de Negócio: Motor de Descontos e Cupons no E-Commerce\"*."
        },
        {
          "line_start": 41,
          "line_end": 41,
          "quote": "* **Distribuição do Material:** Entrega da folha com as regras de negócio simplificadas (Ex.: \"Cupons têm validade até às 23:59 da data limite\", \"Cupom válido subtrai 10% do total\", \"Cupom expirado não altera o valor e emite alerta\")."
        },
