      "justification": "Estão explicitadas tanto a graduação em Ciência da Computação quanto a formação introdutória."
    },
    "learning_objectives": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 5,
          "line_end": 5,
          "quote": "**Objetivo de Aprendizagem:** Simular operações **push** e **pop** em uma pilha, identificar o **topo** e o **estado da pilha** após cada operação, incluindo a **remoção em pilha vazia**.  "
        }
      ],
      "justification": "O objetivo contempla simular push e pop, identificar topo e estado após cada operação e incluir a remoção em pilha vazia."
    },
    "duration_minutes": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 4,
