    "learning_objectives": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 15,
          "line_end": 16,
          "quote": "* Identificar e delimitar partições de equivalência válidas e inválidas a partir de um requisito de software simples.\n* Selecionar valores de teste representativos para cada partição identificada."
        },
        {
          "line_start": 31,
          "line_end": 31,
          "quote": "  * O requisito: *\"O sistema deve aceitar apenas valores inteiros de idade no intervalo de 0 a 120 (inclusive). Quaisquer outros valores numéricos devem ser rejeitados com uma mensagem de erro.\"*"
        }
      ],
      "justification": "Os objetivos incluem identificar partições válidas e inválidas e selecionar representantes. A especificação utilizada concretiza esses desempenhos no campo de idade inteira entre zero e 120, inclusive."
    },
