  "evaluation_id": "eval-45b11ae12b39dbb5ed6ea1a5f98d65ec",
  "requirements": {
    "topic": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 5,
          "line_end": 5,
          "quote": "## **Plano de Aula: Caso de uso de reserva de uma quadra esportiva**"
        }
      ],
      "justification": "O tema corresponde explicitamente ao caso de uso de reserva de uma quadra esportiva."
    },
    "grade_level": {
      "status": "partial",
      "evidence": [
        {
          "line_start": 9,
          "line_end": 10,
          "quote": "- **Disciplina:** Sistemas de Informação / Engenharia de Software / Gestão de Recursos\n- **Turma:** 1º Ano (exemplo)"
        },
        {
          "line_start": 20,
          "line_end": 20,
          "quote": "Introduzir os conceitos de **caso de uso** e **modelagem de sistemas**, aplicando-os ao contexto de **reserva de uma quadra esportiva**."
        }
      ],
      "justification": "O primeiro ano e a introdução aos conceitos representam o caráter introdutório. Entretanto, o plano não especifica graduação em Ciência da Computação; as disciplinas indicadas não estabelecem esse curso e nível."
    },
    "learning_objectives": {
      "status": "partial",
      "evidence": [
        {
          "line_start": 23,
          "line_end": 26,
          "quote": "1. Entender o conceito de **caso de uso** e sua importância no desenvolvimento de sistemas.\n2. Identificar os **atos**, **ações** e **participantes** envolvidos no processo de reserva de uma quadra esportiva.\n3. Desenhar um **diagrama de casos de uso** para o sistema.\n4. Analisar a **interação entre usuários e sistema** no contexto de reserva de quadras."
        },
        {
          "line_start": 32,
          "line_end": 35,
          "quote": "- Introdução a casos de uso\n- Componentes de um caso de uso (ações, atores, fluxos de controle)\n- Exemplo prático: reserva de quadra esportiva\n- Modelo de caso de uso: diagrama de fluxo de atividades"
        }
      ],
      "justification": "A identificação de participantes e atores no contexto da reserva está representada. Há referência genérica a fluxos de controle, mas não se explicita descrever a pré-condição, o fluxo principal e o fluxo alternativo acionado pela indisponibilidade da quadra."
    },
    "duration_minutes": {
      "status": "contradicted",
      "evidence": [
        {
          "line_start": 13,
          "line_end": 13,
          "quote": "- **Duração:** 2 aulas (90 minutos cada)"
        }
      ],
      "justification": "A duração declarada é de duas aulas de 90 minutos, totalizando 180 minutos, incompatível com os 50 minutos solicitados."
    },
    "methodology": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 51,
          "line_end": 53,
          "quote": "1. Apresentação teórica sobre casos de uso e modelagem.\n2. Discussão em grupo sobre os participantes e ações envolvidas no processo de reserva.\n3. Desenho de um **esquema de casos de uso** em grupo."
        },
        {
          "line_start": 71,
          "line_end": 74,
          "quote": "1. Divisão em grupos para elaborar o diagrama de casos de uso.\n2. Apresentação dos grupos.\n3. Discussão e correção dos diagramas.\n4. Análise crítica dos casos de uso."
        }
      ],
      "justification": "A resolução do problema de modelagem da reserva é realizada em grupos, com elaboração conjunta, discussão e revisão dos diagramas. Isso representa resolução colaborativa de problemas, ainda que acompanhada de exposição teórica."
    },
    "materials": {
      "status": "partial",
      "evidence": [
        {
          "line_start": 93,
          "line_end": 96,
          "quote": "- Lápis, caneta, papel\n- Projetor (opcional)\n- Softwares de modelagem (como **StarUML**, **Lucidchart**, ou **draw.io**) para elaboração do diagrama (opcional)\n- Exemplo de diagrama de casos de uso (para referência)"
        }
      ],
      "justification": "Há papel e um exemplo de diagrama como recursos relacionados, mas não se prevê folha com descrição de um sistema de reservas de quadras. O quadro também não está representado; projetor e softwares não são apresentados como esse material."
    },
    "assessment_strategy": {
      "status": "partial",
      "evidence": [
        {
          "line_start": 76,
          "line_end": 79,
          "quote": "**Avaliação:**\n- Participação nas atividades de grupo\n- Diagrama de casos de uso entregue\n- Comentários de qualidade e clareza do modelo"
        },
        {
          "line_start": 85,
          "line_end": 87,
          "quote": "- **Participação nas aulas:** 20%\n- **Diagrama de casos de uso:** 40%\n- **Apresentação e análise crítica:** 40%"
        }
      ],
      "justification": "Existe entrega de uma representação do caso de uso e análise do modelo. Contudo, a avaliação não exige que a entrega explicite ator, pré-condição, fluxo principal e fluxo alternativo, nem que justifique a condição de indisponibilidade que aciona a alternativa."
    }
  },
  "assessments": {
    "instructional_alignment": {
      "score": 3,
      "evidence": [
        {
          "line_start": 23,
          "line_end": 26,
          "quote": "1. Entender o conceito de **caso de uso** e sua importância no desenvolvimento de sistemas.\n2. Identificar os **atos**, **ações** e **participantes** envolvidos no processo de reserva de uma quadra esportiva.\n3. Desenhar um **diagrama de casos de uso** para o sistema.\n4. Analisar a **interação entre usuários e sistema** no contexto de reserva de quadras."
        },
        {
          "line_start": 71,
          "line_end": 79,
          "quote": "1. Divisão em grupos para elaborar o diagrama de casos de uso.\n2. Apresentação dos grupos.\n3. Discussão e correção dos diagramas.\n4. Análise crítica dos casos de uso.\n\n**Avaliação:**\n- Participação nas atividades de grupo\n- Diagrama de casos de uso entregue\n- Comentários de qualidade e clareza do modelo"
        }
      ],
      "justification": "Os objetivos de desenhar e analisar são retomados nas atividades de elaboração, discussão e análise, bem como na entrega avaliada. A lacuna pontual está na avaliação genérica de qualidade e clareza, sem explicitar como verifica a compreensão conceitual e a identificação dos participantes previstas nos objetivos."
    },
    "textual_coherence": {
      "score": 4,
      "evidence": [
        {
          "line_start": 51,
          "line_end": 53,
          "quote": "1. Apresentação teórica sobre casos de uso e modelagem.\n2. Discussão em grupo sobre os participantes e ações envolvidas no processo de reserva.\n3. Desenho de um **esquema de casos de uso** em grupo."
        },
        {
          "line_start": 71,
          "line_end": 74,
          "quote": "1. Divisão em grupos para elaborar o diagrama de casos de uso.\n2. Apresentação dos grupos.\n3. Discussão e correção dos diagramas.\n4. Análise crítica dos casos de uso."
        },
        {
          "line_start": 85,
          "line_end": 87,
          "quote": "- **Participação nas aulas:** 20%\n- **Diagrama de casos de uso:** 40%\n- **Apresentação e análise crítica:** 40%"
        }
      ],
      "justification": "A sequência progride de introdução e discussão para elaboração, apresentação e revisão do modelo. A avaliação retoma os produtos e ações descritos, com pesos internamente consistentes. A duração diferente da solicitada é uma divergência do alvo, não uma contradição interna."
    }
  }
