      "evidence": [
        {
          "line_start": 6,
          "line_end": 6,
          "quote": "**Objetivo de Aprendizagem:** Escrever uma consulta SQL com GROUP BY e COUNT para contar pedidos por cliente e conferir o resultado com base em uma tabela pequena."
        }
      ],
      "justification": "O objetivo contempla escrever a consulta com GROUP BY e COUNT, contar pedidos por cliente e conferir o resultado a partir de uma tabela pequena."
    },
    "duration_minutes": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 4,
          "line_end": 4,
          "quote": "**Duração:** 50 minutos  "
        }
      ],
      "justification": "A duração declarada é de 50 minutos. As quatro etapas principais, de 5, 20, 15 e 10 minutos, também totalizam 50 minutos, sem necessidade de inferir tempos de subetapas."
