{
  "schema_version": "eduadocs-requirement-judge-response-v2.0.0",
  "rubric_version": "eduadocs-requirement-judge-v2.0.0",
  "evaluation_id": "eval-66bbe06b0d41a74ed8bde87b96b49da1",
  "requirements": {
    "topic": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 5,
          "line_end": 5,
          "quote": "## **Plano de Aula: Caso de uso de reserva de uma quadra esportiva**"
        }
      ],
      "justification": "O tema é explicitamente o caso de uso de reserva de uma quadra esportiva."
    },
    "grade_level": {
      "status": "partial",
      "evidence": [
        {
          "line_start": 9,
          "line_end": 10,
          "quote": "- **Disciplina:** Sistemas de Informação / Engenharia de Software / Gestão de Recursos\n- **Turma:** 1º Ano (exemplo)"
        },
        {
          "line_start": 20,
          "line_end": 20,
          "quote": "Introduzir os conceitos de **caso de uso** e **modelagem de sistemas**, aplicando-os ao contexto de **reserva de uma quadra esportiva**."
        }
      ],
      "justification": "O caráter introdutório está representado pela introdução dos conceitos e pela indicação de primeiro ano. Entretanto, a indicação de disciplinas não estabelece que a turma seja de graduação em Ciência da Computação, componente específico que não está representado."
    },
    "learning_objectives": {
      "status": "partial",
      "evidence": [
        {
          "line_start": 23,
          "line_end": 26,
          "quote": "1. Entender o conceito de **caso de uso** e sua importância no desenvolvimento de sistemas.\n2. Identificar os **atos**, **ações** e **participantes** envolvidos no processo de reserva de uma quadra esportiva.\n3. Desenhar um **diagrama de casos de uso** para o sistema.\n4. Analisar a **interação entre usuários e sistema** no contexto de reserva de quadras."
        },
        {
          "line_start": 32,
          "line_end": 35,
          "quote": "- Introdução a casos de uso\n- Componentes de um caso de uso (ações, atores, fluxos de controle)\n- Exemplo prático: reserva de quadra esportiva\n- Modelo de caso de uso: diagrama de fluxo de atividades"
        }
      ],
      "justification": "O contexto de reserva e a identificação dos participantes/atores estão representados. Há referência genérica a fluxos de controle, mas não ao desempenho de descrever uma pré-condição, um fluxo principal e um fluxo alternativo especificamente acionado pela indisponibilidade da quadra."
    },
    "duration_minutes": {
      "status": "contradicted",
      "evidence": [
        {
          "line_start": 13,
          "line_end": 13,
          "quote": "- **Duração:** 2 aulas (90 minutos cada)"
        }
      ],
      "justification": "O plano declara duas aulas de 90 minutos cada, totalizando 180 minutos, incompatíveis com os 50 minutos solicitados."
    },
    "methodology": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 51,
          "line_end": 53,
          "quote": "1. Apresentação teórica sobre casos de uso e modelagem.\n2. Discussão em grupo sobre os participantes e ações envolvidas no processo de reserva.\n3. Desenho de um **esquema de casos de uso** em grupo."
        },
        {
          "line_start": 71,
          "line_end": 74,
          "quote": "1. Divisão em grupos para elaborar o diagrama de casos de uso.\n2. Apresentação dos grupos.\n3. Discussão e correção dos diagramas.\n4. Análise crítica dos casos de uso."
        }
      ],
      "justification": "A elaboração conjunta de uma solução de modelagem para o processo de reserva, com discussão, apresentação e revisão dos diagramas, representa resolução colaborativa de problemas. A exposição teórica adicional não contradiz essa metodologia."
    },
    "materials": {
      "status": "partial",
      "evidence": [
        {
          "line_start": 93,
          "line_end": 96,
          "quote": "- Lápis, caneta, papel\n- Projetor (opcional)\n- Softwares de modelagem (como **StarUML**, **Lucidchart**, ou **draw.io**) para elaboração do diagrama (opcional)\n- Exemplo de diagrama de casos de uso (para referência)"
        }
      ],
      "justification": "Há papel entre os recursos, mas não uma folha com descrição do sistema de reservas de quadras; o exemplo de diagrama não é apresentado como essa descrição. O quadro também não está previsto. Portanto, os materiais específicos solicitados estão apenas parcialmente representados."
    },
    "assessment_strategy": {
      "status": "partial",
      "evidence": [
        {
          "line_start": 76,
          "line_end": 79,
          "quote": "**Avaliação:**\n- Participação nas atividades de grupo\n- Diagrama de casos de uso entregue\n- Comentários de qualidade e clareza do modelo"
        }
      ],
      "justification": "Há entrega de um produto relacionado ao caso de uso, na forma de diagrama. Contudo, a avaliação não exige que a entrega explicite ator, pré-condição, fluxo principal e fluxo alternativo, nem que justifique a condição que aciona a alternativa. A referência genérica à clareza do modelo não cobre esses componentes."
    }
  },
  "assessments": {
    "instructional_alignment": {
      "score": 4,
      "evidence": [
        {
          "line_start": 23,
          "line_end": 26,
          "quote": "1. Entender o conceito de **caso de uso** e sua importância no desenvolvimento de sistemas.\n2. Identificar os **atos**, **ações** e **participantes** envolvidos no processo de reserva de uma quadra esportiva.\n3. Desenhar um **diagrama de casos de uso** para o sistema.\n4. Analisar a **interação entre usuários e sistema** no contexto de reserva de quadras."
        },
        {
          "line_start": 71,
          "line_end": 79,
          "quote": "1. Divisão em grupos para elaborar o diagrama de casos de uso.\n2. Apresentação dos grupos.\n3. Discussão e correção dos diagramas.\n4. Análise crítica dos casos de uso.\n\n**Avaliação:**\n- Participação nas atividades de grupo\n- Diagrama de casos de uso entregue\n- Comentários de qualidade e clareza do modelo"
        }
      ],
      "justification": "Os objetivos próprios do plano de identificar participantes, desenhar o diagrama e analisar interações se articulam explicitamente à discussão, elaboração e análise em grupo. A avaliação recolhe o diagrama e considera participação e clareza do modelo, mantendo alinhamento textual com esses desempenhos, independentemente das lacunas em relação ao alvo."
    },
    "textual_coherence": {
      "score": 4,
      "evidence": [
        {
