      "evidence": [
        {
          "line_start": 6,
          "line_end": 6,
          "quote": "**Nível educacional:** Graduação em Ciência da Computação – Formação introdutória  "
        }
      ],
      "justification": "Estão explicitamente representados o nível de graduação, o curso de Ciência da Computação e o caráter introdutório da formação."
    },
