  "requirements": {
    "topic": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 1,
          "line_end": 1,
          "quote": "**Plano de Aula: Caso de Uso – Reserva de uma Quadra Esportiva**"
        }
      ],
      "justification": "O plano trata explicitamente de um caso de uso de reserva de uma quadra esportiva."
    },
    "grade_level": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 5,
          "line_end": 5,
          "quote": "**Nível de Ensino:** Graduação em Ciência da Computação  "
        },
        {
          "line_start": 116,
          "line_end": 116,
          "quote": "- Pode ser usado como introdução a casos de uso ou como revisão de conceitos básicos."
        }
      ],
      "justification": "A graduação em Ciência da Computação está declarada, e o caráter introdutório está representado pela introdução a casos de uso e aos conceitos básicos."
    },
    "learning_objectives": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 9,
          "line_end": 9,
          "quote": "- Descrever **ator**, **pré-condição**, **fluxo principal** e **fluxo alternativo** de indisponibilidade de uma quadra em um caso de uso de reserva.  "
        }
      ],
      "justification": "O objetivo contempla descrever ator, pré-condição, fluxo principal e fluxo alternativo por indisponibilidade da quadra, todos vinculados ao caso de uso de reserva."
    },
    "duration_minutes": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 6,
          "line_end": 6,
          "quote": "**Carga Horária:** 50 minutos  "
        }
      ],
      "justification": "A duração declarada é de 50 minutos. As cinco etapas principais totalizam 5 + 10 + 25 + 5 + 5 = 50 minutos; os quatro passos internos detalham os 25 minutos da terceira etapa, sem serem somados novamente."
    },
    "methodology": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 7,
          "line_end": 7,
          "quote": "**Metodologia:** Resolução Colaborativa de Problemas  "
        },
        {
          "line_start": 26,
          "line_end": 31,
          "quote": "- Pequenos grupos de 3 a 4 estudantes.\n- Tarefa: Ler e compreender o sistema de reservas de quadras.\n- Perguntas orientadoras:\n  - Quem são os atores envolvidos?\n  - O que é necessário para realizar uma reserva?\n  - O que acontece se a quadra estiver indisponível?"
        },
        {
          "line_start": 117,
          "line_end": 117,
          "quote": "- Recomenda-se a participação ativa dos alunos, com discussão e desenho dos fluxos."
        }
      ],
      "justification": "A resolução colaborativa de problemas está declarada e representada por pequenos grupos que analisam o sistema, discutem questões do problema e desenham os fluxos."
    },
    "materials": {
      "status": "uncertain",
      "evidence": [
        {
          "line_start": 101,
          "line_end": 103,
          "quote": "- **Quadro de casos de uso** (exemplo de estrutura)\n- **Folha de descrição do sistema** (exemplo de sistema de reservas de quadras)\n- **Folha de resposta com caso de uso** (para entrega)"
        },
        {
          "line_start": 25,
          "line_end": 25,
          "quote": "- Distribuir o **quadro de casos de uso** e a **folha de descrição do sistema**."
        }
      ],
      "justification": "A folha com descrição do sistema de reservas de quadras está explicitamente contemplada. Já 'quadro de casos de uso', descrito como exemplo de estrutura e como algo a distribuir, pode designar um modelo ou tabela, não necessariamente o quadro solicitado. O texto não permite decidir com segurança se esse segundo material está contemplado."
    },
    "assessment_strategy": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 78,
          "line_end": 86,
          "quote": "- Entregar um **caso de uso** com os seguintes elementos:\n  - **Atores**: Usuário do sistema\n  - **Pré-condição**: O usuário está autenticado no sistema\n  - **Fluxo principal**: Reserva de quadra com disponibilidade\n  - **Fluxo alternativo**: Quadra indisponível\n\n- Justificar a **condição que aciona o fluxo alternativo**:\n  - A condição que aciona o fluxo alternativo é: **a quadra não está disponível no horário escolhido**.\n  - Esta estratégia é usada para **tratar situações de falha ou inesperadas**, garantindo que o sistema informe o usuário de forma clara e útil."
        }
      ],
      "justification": "A avaliação solicita entregar um caso de uso contendo ator, pré-condição e os dois fluxos. Também solicita justificar a condição que aciona a alternativa, identificada como indisponibilidade da quadra no horário escolhido."
    }
  },
  "assessments": {
    "instructional_alignment": {
      "score": 3,
      "evidence": [
        {
          "line_start": 9,
          "line_end": 9,
          "quote": "- Descrever **ator**, **pré-condição**, **fluxo principal** e **fluxo alternativo** de indisponibilidade de uma quadra em um caso de uso de reserva.  "
        },
        {
          "line_start": 78,
          "line_end": 85,
          "quote": "- Entregar um **caso de uso** com os seguintes elementos:\n  - **Atores**: Usuário do sistema\n  - **Pré-condição**: O usuário está autenticado no sistema\n  - **Fluxo principal**: Reserva de quadra com disponibilidade\n  - **Fluxo alternativo**: Quadra indisponível\n\n- Justificar a **condição que aciona o fluxo alternativo**:\n  - A condição que aciona o fluxo alternativo é: **a quadra não está disponível no horário escolhido**."
        },
        {
          "line_start": 72,
          "line_end": 72,
          "quote": "- Compartilhar a definição de fluxo alternativo: **caminho que ocorre quando a pré-condição não é satisfeita**."
        }
      ],
      "justification": "Objetivo, passos da atividade e produto avaliativo retomam os mesmos quatro componentes do caso de uso. Há uma lacuna localizada: a definição compartilhada na atividade vincula a alternativa ao não atendimento da pré-condição, enquanto a avaliação estabelece autenticação como pré-condição e indisponibilidade como gatilho da alternativa."
    },
    "textual_coherence": {
      "score": 2,
      "evidence": [
        {
          "line_start": 45,
          "line_end": 46,
          "quote": "- Exemplo: O usuário precisa estar autenticado no sistema.\n- Compartilhar a definição de pré-condição: **condição que deve ser atendida antes de iniciar o caso de uso**."
        },
        {
          "line_start": 72,
          "line_end": 72,
          "quote": "- Compartilhar a definição de fluxo alternativo: **caminho que ocorre quando a pré-condição não é satisfeita**."
        },
        {
          "line_start": 84,
          "line_end": 85,
          "quote": "- Justificar a **condição que aciona o fluxo alternativo**:\n  - A condição que aciona o fluxo alternativo é: **a quadra não está disponível no horário escolhido**."
        }
      ],
      "justification": "A sequência de introdução, trabalho em grupos, construção dos componentes, avaliação e conclusão é organizada, e os tempos são consistentes. Entretanto, há incompatibilidade interna relevante: a pré-condição é autenticação, mas o fluxo alternativo é definido como decorrência de sua não satisfação e depois acionado pela indisponibilidade da quadra, sem que o texto relacione essas condições."
    }
  }
}

