  "requirements": {
    "topic": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 5,
          "line_end": 5,
          "quote": "## **Plano de Aula: Critérios de aceitação de aplicação de cupom em uma compra**"
        },
        {
          "line_start": 29,
          "line_end": 32,
          "quote": "### **2. Critérios de aceitação de cupons**\n- **Validade do cupom:** Data de início e fim da validade.\n- **Prazo de uso:** Quantos dias após a emissão o cupom pode ser usado.\n- **Valor do cupom:** Percentual ou valor fixo."
        }
      ],
      "justification": "O tema de critérios para aceitar a aplicação de um cupom em uma compra está explicitamente identificado e desenvolvido em condições como validade e valor."
    },
    "grade_level": {
      "status": "contradicted",
      "evidence": [
        {
          "line_start": 1,
          "line_end": 1,
          "quote": "Claro! A seguir está um **Plano de Aula** sobre o tema **\"Critérios de aceitação de aplicação de cupom em uma compra\"**, destinado a alunos do ensino médio ou superior, com foco em matemática, economia e lógica de negócios."
        },
        {
          "line_start": 7,
          "line_end": 7,
          "quote": "### **Disciplina:** Matemática, Economia ou Administração  "
        }
      ],
      "justification": "O ensino superior aparece como possibilidade, mas o público inclui também ensino médio e a vinculação disciplinar declarada é Matemática, Economia ou Administração, em vez de graduação em Ciência da Computação. A formação introdutória não é especificada."
    },
    "learning_objectives": {
      "status": "partial",
      "evidence": [
        {
          "line_start": 15,
          "line_end": 18,
          "quote": "1. Identificar os critérios que determinam a aplicação de um cupom em uma compra.\n2. Analisar a validade e o alcance de um cupom de desconto.\n3. Compreender a relação entre cupons e custo-benefício de uma compra.\n4. Aplicar os critérios de aceitação em situações reais de compras."
        }
      ],
      "justification": "Há objetivos relativos a critérios de aplicação e análise de validade. Não se prevê especificar dois critérios no formato Dado Quando Então, contemplar separadamente cupom válido e expirado, nem justificar os resultados observáveis desses dois casos."
    },
    "duration_minutes": {
      "status": "contradicted",
      "evidence": [
        {
          "line_start": 8,
          "line_end": 8,
          "quote": "### **Carga horária:** 2 aulas (45 minutos cada)  "
        }
      ],
      "justification": "A carga declarada é de 90 minutos, incompatível com os 50 minutos requeridos."
    },
    "methodology": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 65,
          "line_end": 67,
          "quote": "**3. Atividade de grupo (15 min):**  \n- Alunos recebem folhas com diferentes cupons e devem identificar os critérios de aceitação.\n- Discussão em grupo sobre os critérios mais importantes."
        },
        {
          "line_start": 78,
          "line_end": 84,
          "quote": "**2. Aplicação prática (20 min):**  \n- Alunos analisam diferentes cenários de compras com cupons.\n- Calculam o valor real do desconto e avaliam se é vantajoso.\n\n**3. Discussão em grupo (15 min):**  \n- Alunos apresentam suas análises.\n- Professor faz correção e complementa os conceitos."
        }
      ],
      "justification": "A identificação conjunta de critérios, a análise de problemas de compra e a discussão coletiva das soluções representam resolução colaborativa de problemas, mesmo com momentos expositivos adicionais."
    },
    "materials": {
      "status": "partial",
      "evidence": [
        {
          "line_start": 47,
          "line_end": 50,
          "quote": "- Folhas de atividade com exemplos de cupons.\n- Calculadora.\n- Projetor de vídeo ou tela para apresentação.\n- Fichas de estudo com questões de análise de cupons."
        },
        {
          "line_start": 66,
          "line_end": 66,
          "quote": "- Alunos recebem folhas com diferentes cupons e devem identificar os critérios de aceitação."
        }
      ],
      "justification": "As folhas com cupons para identificar critérios representam parcialmente o material impresso solicitado. Não há quadro, nem especificação de uma folha com regras de uso de cupons em um carrinho de compras."
    },
    "assessment_strategy": {
      "status": "partial",
      "evidence": [
        {
          "line_start": 92,
          "line_end": 96,
          "quote": "## **Avaliação:**\n- Participação nas atividades de grupo.\n- Trabalho de análise prática dos cupons.\n- Respostas às questões de avaliação.\n- Entrega de um relatório com a análise de um cupom fictício."
        }
      ],
      "justification": "Há avaliação por análise e entrega escrita sobre cupons. Contudo, não é solicitada a entrega de dois cenários Dado Quando Então, seus resultados esperados ou a distinção explícita entre cupom válido e expirado."
    }
  },
  "assessments": {
    "instructional_alignment": {
      "score": 3,
      "evidence": [
        {
          "line_start": 15,
          "line_end": 18,
          "quote": "1. Identificar os critérios que determinam a aplicação de um cupom em uma compra.\n2. Analisar a validade e o alcance de um cupom de desconto.\n3. Compreender a relação entre cupons e custo-benefício de uma compra.\n4. Aplicar os critérios de aceitação em situações reais de compras."
        },
        {
          "line_start": 78,
          "line_end": 80,
          "quote": "**2. Aplicação prática (20 min):**  \n- Alunos analisam diferentes cenários de compras com cupons.\n- Calculam o valor real do desconto e avaliam se é vantajoso."
        },
        {
          "line_start": 93,
          "line_end": 96,
          "quote": "- Participação nas atividades de grupo.\n- Trabalho de análise prática dos cupons.\n- Respostas às questões de avaliação.\n- Entrega de um relatório com a análise de um cupom fictício."
        }
      ],
      "justification": "Os objetivos próprios do plano de identificar critérios, analisar validade e avaliar custo-benefício se relacionam às atividades e à análise prática avaliada. A lacuna é a pouca explicitação do que as questões e o relatório devem demonstrar para verificar cada objetivo."
    },
    "textual_coherence": {
      "score": 3,
      "evidence": [
        {
          "line_start": 8,
          "line_end": 8,
          "quote": "### **Carga horária:** 2 aulas (45 minutos cada)  "
        },
        {
          "line_start": 57,
          "line_end": 69,
          "quote": "**1. Introdução (10 min):**  \n- Apresentação do tema e objetivos da aula.\n- Breve história dos cupons de desconto.\n\n**2. Explicação teórica (20 min):**  \n- Definição e tipos de cupons.\n- Critérios de aceitação de cupons.\n\n**3. Atividade de grupo (15 min):**  \n- Alunos recebem folhas com diferentes cupons e devem identificar os critérios de aceitação.\n- Discussão em grupo sobre os critérios mais importantes.\n\n**4. Avaliação inicial (5 min):**  "
        }
      ],
      "justification": "A sequência de introdução, explicação, análise e aplicação é coerente. Há uma incompatibilidade pontual de tempo: as etapas sequenciais da primeira aula somam 50 minutos, embora cada aula seja declarada como tendo 45 minutos. Não há indicação de sobreposição dessas etapas."
    }
  }
}

