          "line_start": 74,
          "line_end": 79,
          "quote": "   // Processamento: percorrer o vetor\n   para i de 1 ate 5 faca\n      se (vetor_numeros[i] % 2 = 0) entao\n         contador_pares <- contador_pares + 1\n      fimse\n   fimpara"
        },
