  "evaluation_id": "eval-d0187f6a3c50881124011c5667313cd9",
  "requirements": {
    "topic": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 5,
          "line_end": 5,
          "quote": "* **Tópico:** Critérios de Aceitação na Aplicação de Cupons de Desconto em E-commerce"
        }
      ],
      "justification": "O tema declarado contempla critérios de aceitação para aplicação de cupons em compras."
    },
    "grade_level": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 4,
          "line_end": 4,
          "quote": "* **Curso:** Bacharelado em Ciência da Computação (Fase Introdutória / Engenharia de Software I)"
        }
      ],
      "justification": "O bacharelado corresponde à graduação em Ciência da Computação, e a fase introdutória está explicitamente indicada."
    },
    "learning_objectives": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 13,
          "line_end": 14,
          "quote": "* Especificar tecnicamente dois critérios de aceitação utilizando a sintaxe **Dado-Quando-Então** (*Given-When-Then* / Gherkin) para os cenários de **cupom válido** e **cupom expirado**.\n* Justificar os resultados observáveis (efeitos colaterais no sistema: atualização de valores monetários e emissão de mensagens de erro/estado) em cada cenário."
        }
      ],
      "justification": "Os objetivos explicitam os dois critérios, o formato Dado Quando Então, a distinção entre cupom válido e expirado e a justificativa dos resultados observáveis."
    },
    "duration_minutes": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 6,
          "line_end": 6,
          "quote": "* **Duração:** 50 minutos"
