  "evaluation_id": "eval-df3d2b642c15c2b3a007ecbb5a9c133d",
  "requirements": {
    "topic": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 18,
          "line_end": 19,
          "quote": "   - Estrutura de dados linear que segue a política **LIFO** (último a entrar, primeiro a sair).\n   - Operações principais: **push** (inserir), **pop** (remover), **top** (consultar o elemento no topo)."
        }
      ],
      "justification": "O plano aborda operações de pilha e explicita a política LIFO."
    },
    "grade_level": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 2,
          "line_end": 3,
          "quote": "**Nível:** Graduação em Ciência da Computação  \n**Formação:** Introductory  "
        }
      ],
      "justification": "Estão explicitados tanto a graduação em Ciência da Computação quanto o caráter introdutório da formação."
    },
    "learning_objectives": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 11,
          "line_end": 11,
          "quote": "Simular operações **push** e **pop** em uma pilha com política LIFO (Last In, First Out), identificar o **topo** da pilha após cada operação e tratar corretamente a remoção de elementos de uma pilha vazia."
        },
        {
          "line_start": 65,
          "line_end": 65,
          "quote": "   - Cada grupo deve **anotar** o estado da pilha e o topo após cada operação."
        }
      ],
      "justification": "A simulação de push e pop, a identificação do topo e o tratamento da remoção em pilha vazia aparecem no objetivo. A identificação do estado após cada operação também está representada na tarefa de registro."
    },
