      ],
      "justification": "O plano contempla pilhas, sua política LIFO e as operações de inserção e remoção."
    },
    "grade_level": {
      "status": "supported",
      "evidence": [
        {
          "line_start": 1,
          "line_end": 1,
          "quote": "Claro! A seguir está um **Plano de Aula** sobre o tema **\"Operações de Pilha com política LIFO\"**, destinado a alunos do ensino médio ou inicial da graduação em Ciência da Computação ou áreas afins."
        }
      ],
      "justification": "A graduação inicial em Ciência da Computação está explicitamente incluída no público. A inclusão adicional do ensino médio e de áreas afins não exclui o nível solicitado."
